class EchoAgent:
    def __init__(self, prefix):
        self.prefix = prefix
    def process(self, data):
        return f"{self.prefix}: {data}"

def run_serial(agents, input_data):
    current = input_data
    for agent in agents:
        current = agent.process(current)
    return current

def run_parallel(agents, input_data):
    results = []
    for agent in agents:
        results.append(agent.process(input_data))
    return results

# 测试
agents = [EchoAgent("A"), EchoAgent("B")]
serial_result = run_serial(agents, "start")
parallel_result = run_parallel(agents, "data")
print(f"Serial: {serial_result}")
print(f"Parallel: {parallel_result}")

