steps.solutionCode:
class Researcher:
    def process(self, task):
        return f"Researched: {task}"

class Writer:
    def process(self, task):
        return f"Wrote: {task}"

class TaskDecomposer:
    def decompose(self, task_description: str) -> list:
        subtasks = []
        if 'research' in task_description.lower():
            subtasks.append({'task': 'AI history', 'role': 'researcher'})
        if 'write' in task_description.lower():
            subtasks.append({'task': 'article on AI history', 'role': 'writer'})
        return subtasks

class Coordinator:
    def __init__(self):
        self.agents = {
            'researcher': Researcher(),
            'writer': Writer()
        }
        self.decomposer = TaskDecomposer()

    def run(self, task_description: str) -> list:
        subtasks = self.decomposer.decompose(task_description)
        results = []
        for subtask in subtasks:
            agent = self.agents[subtask['role']]
            result = agent.process(subtask['task'])
            results.append(result)
        return results

# 测试
coord = Coordinator()
result = coord.run("Research AI history and write an article")
print(result)

